FBProgram.STSource:
(* On delay, in seconds *)
T1 (IN := IN, PT := DINT_TO_TIME(PT_S * 1000));
Q := T1.Q;

(* Magnus formula *)
IF RH > 0.5 THEN
    G := LN(RH / 100.0) + (17.62 * TEMP) / (243.12 + TEMP);
    DP := 243.12 * G / (17.62 - G);
ELSE
    DP := -50.0;
END_IF;

attribute.value:
The function assigns the largest input value to the output. The data types of all input values and output values must be identical.
The number of inputs can be increased.
Formula OUT = MAX {IN1, IN2, .., INn}

FBProgram.STSource:
(* PI control, 1 s sample time, anti-windup, bumpless tracking when disabled *)
IF DIRECT THEN E := PV - SP; ELSE E := SP - PV; END_IF;
IF NOT ENABLE THEN
    I_TERM := TRK_VAL - KP * E;
    OUT := TRK_VAL;
ELSIF SAMPLE THEN
    IF TI > 0.0 THEN I_TERM := I_TERM + KP * E / TI; END_IF;
    Y := KP * E + I_TERM;
    IF Y > OUT_MAX THEN Y := OUT_MAX; I_TERM := OUT_MAX - KP * E; END_IF;
    IF Y < OUT_MIN THEN Y := OUT_MIN; I_TERM := OUT_MIN - KP * E; END_IF;
    OUT := Y;
END_IF;

(*=====================================================
   Function: analog scaling + 4-level alarms + alarm delay + hysteresis + hold on wire break
   For: Schneider M340/M580
   Platform: EcoStruxure
   Language: ST
   Zhao Jianchun  jianchun.zhao@jci.com
======================================================*)
(* 1. Range calculation *)
    RawRange_INT  :=  RawMax-RawMin;
    RawRange      :=  INT_TO_REAL(IN := RawRange_INT);
    ScaleRange    := ScaleMax - ScaleMin;
    UnderRange    := AI_Raw < (RawMin - 400);
    OverRange     := AI_Raw > (RawMax + 400);

(* 2. Engineering scaling + hold on wire break *)
IF NOT UnderRange AND NOT OverRange THEN
    RawDelta_Int := AI_Raw - RawMin;
    RawDelta := INT_TO_REAL(IN := RawDelta_Int);
    AI_PV    := ScaleMin + (RawDelta / RawRange) * ScaleRange;
    LastValue:= AI_PV;
ELSE
    AI_PV    := LastValue; 
END_IF;

(* Low-low alarm *)
  IF (Not LL_Pre) And AI_PV < Alarm_LL_Value THEN 
    LL_Pre:= true;
  END_IF;
  IF LL_Pre And AI_PV > (Alarm_LL_Value + SP_Hyst)  THEN 
    LL_Pre:= false;
  END_IF;
(* Low-low alarm *)
  IF (Not L_Pre) And AI_PV < Alarm_L_Value THEN 
    L_Pre:= true;
   END_IF;
   IF L_Pre And AI_PV > (Alarm_L_Value + SP_Hyst)  THEN 
    L_Pre:= false;
   END_IF;
(* High alarm *)
   IF (Not H_Pre) And AI_PV > Alarm_H_Value THEN 
    H_Pre:= true;
   END_IF;
   IF H_Pre And AI_PV < (Alarm_H_Value - SP_Hyst)  THEN 
    H_Pre:= false;
   END_IF;
(* High-high alarm *)
  IF (Not HH_Pre) And AI_PV > Alarm_HH_Value THEN 
    HH_Pre:= true;
   END_IF;
  IF HH_Pre And AI_PV < (Alarm_HH_Value - SP_Hyst)  THEN 
    HH_Pre:= false;
  END_IF;

IF NOT Alarm_Enable then
   LL_Pre:= false;
    L_Pre:= false;
    H_Pre:= false;
   HH_Pre:= false;
END_IF;
(* Alarm delay output *)

Alarm_Delay_Time:=DINT_TO_Time(Alarm_Delay_SP *1000); 


LL_Timer (IN := LL_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_LL);

L_Timer  (IN := L_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_L);

H_Timer  (IN := H_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_H);

HH_Timer  (IN := HH_Pre,
       	  PT := Alarm_Delay_Time,
          Q  => Alarm_HH);

(* Sensor health: wire break/out of range (4977..28300 = approx. 3.6..20.5 mA), outside plausible range, manually disabled *)
IF SIM THEN
    BAD := SIM_FAIL OR OOS OR (SIM_PV < LO) OR (SIM_PV > HI);
    IF NOT BAD THEN LAST := SIM_PV; END_IF;
ELSE
    BAD := OOS OR (RAW < 4977) OR (RAW > 28300) OR (PV < LO) OR (PV > HI);
    IF NOT BAD THEN LAST := PV; END_IF;
END_IF;
VAL := LAST;
OK := NOT BAD;
IF BAD THEN
    IF SEC_P AND (CNT < DLY) THEN CNT := CNT + 1; END_IF;
ELSE
    CNT := 0;
END_IF;
ALM := BAD AND (CNT >= DLY);

