IF NOT RCV_ACT AND P06_Known[2] AND P06_Fresh[2] AND NOT P06_Local[2] THEN CH2_CMD_BITS := CH2_CMD_BITS OR 16#0020; END_IF;      (* command block valid (cleared during the restart recovery) *)
CH2_CMD_SPD := REAL_TO_INT(CHPVSD_SEQ_OUT * 100.0);
CH2_CMD_TSP := REAL_TO_INT(CHS_TSP_OUT * 100.0);
CH2_CMD_CHWST := REAL_TO_INT(CHWS_T01_T02 * 100.0);
CH2_CMD_OAT := REAL_TO_INT(OA_T * 100.0);
