IF NOT RCV_ACT AND P06_Known[3] AND P06_Fresh[3] AND NOT P06_Local[3] THEN CH3_CMD_BITS := CH3_CMD_BITS OR 16#0020; END_IF;      (* command block valid (cleared during the restart recovery) *)
CH3_CMD_SPD := REAL_TO_INT(CHPVSD_SEQ_OUT * 100.0);
CH3_CMD_TSP := REAL_TO_INT(CHS_TSP_OUT * 100.0);
