(* ---- alarm memory over a cold start (2026-10-19) ----
   ALM_MEM (%MW3000.., kept with 'Initialize %MWi on cold start' off) = HMI_X of the last scan.
   First scan after a cold start (ALM_MEM_DONE = FALSE) with a matching layout signature ALM_SIG:
   the alarms active before the power loss stay active for ALM_HOLD_TM s, until the live alarm comes
   back by itself, or until an alarm reset; latched alarms go back into their latch variable. *)
IF NOT ALM_MEM_DONE THEN
    ALM_MEM_DONE := TRUE;
    ALM_HOLD := ALM_SIG = 6516;
    ALM_HOLD_CNT := 0;
    IF ALM_HOLD_TM <= 0 THEN ALM_HOLD_TM := 1200; END_IF;
    FOR HMI_K := 0 TO 1167 DO
        ALM_OLD[HMI_K] := ALM_HOLD AND ((ALM_MEM[HMI_K / 16] AND SHL(16#0001, INT_TO_UINT(HMI_K MOD 16))) <> 0);
    END_FOR;
    IF ALM_HOLD THEN
        ALM_SYSFL := ALM_OLD[1153];
        ALM_LEAD_FAIL := ALM_OLD[1156];
        ALM_HSBY_SWAP := ALM_OLD[1158];
    END_IF;
END_IF;
IF ALM_HOLD AND SEC_P THEN ALM_HOLD_CNT := ALM_HOLD_CNT + 1; END_IF;
IF (ALM_HOLD_CNT >= ALM_HOLD_TM) OR (RST_HOLD > 0) THEN ALM_HOLD := FALSE; END_IF;

IF SIM_EN THEN ALM_OLD[0] := FALSE; END_IF;  HMI_X[0] := SIM_EN OR (ALM_HOLD AND ALM_OLD[0]);
IF SIM_M340_EN THEN ALM_OLD[1] := FALSE; END_IF;  HMI_X[1] := SIM_M340_EN OR (ALM_HOLD AND ALM_OLD[1]);
HMI_X[2] := ALM_LEAK_ANY;
HMI_X[3] := ALM_AI_ANY;
IF A_RLK01_F THEN ALM_OLD[16] := FALSE; END_IF;  HMI_X[16] := A_RLK01_F OR (ALM_HOLD AND ALM_OLD[16]);
IF A_RLK02_F THEN ALM_OLD[17] := FALSE; END_IF;  HMI_X[17] := A_RLK02_F OR (ALM_HOLD AND ALM_OLD[17]);
IF A_RLK03_F THEN ALM_OLD[18] := FALSE; END_IF;  HMI_X[18] := A_RLK03_F OR (ALM_HOLD AND ALM_OLD[18]);
IF A_RLK04_F THEN ALM_OLD[19] := FALSE; END_IF;  HMI_X[19] := A_RLK04_F OR (ALM_HOLD AND ALM_OLD[19]);
IF A_RLK05_F THEN ALM_OLD[20] := FALSE; END_IF;  HMI_X[20] := A_RLK05_F OR (ALM_HOLD AND ALM_OLD[20]);
IF A_RLK06_F THEN ALM_OLD[21] := FALSE; END_IF;  HMI_X[21] := A_RLK06_F OR (ALM_HOLD AND ALM_OLD[21]);
IF A_RLK07_F THEN ALM_OLD[22] := FALSE; END_IF;  HMI_X[22] := A_RLK07_F OR (ALM_HOLD AND ALM_OLD[22]);
IF A_RLK08_F THEN ALM_OLD[23] := FALSE; END_IF;  HMI_X[23] := A_RLK08_F OR (ALM_HOLD AND ALM_OLD[23]);
